package com.abikananda.ipo.api; import com.abikananda.ipo.domain.Ipo; import com.abikananda.ipo.repository.IpoRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/dashboard") public class DashboardController {private final IpoRepository ipos;public DashboardController(IpoRepository i){ipos=i;}@GetMapping("/summary") Map<String,Object> summary(){var all=ipos.findAll();return Map.of("total",all.size(),"open",all.stream().filter(x->x.getStatus()==Ipo.IpoStatus.OPEN).count(),"upcoming",all.stream().filter(x->x.getStatus()==Ipo.IpoStatus.UPCOMING).count(),"mainboard",all.stream().filter(x->x.getType()==Ipo.IpoType.MAINBOARD).count(),"sme",all.stream().filter(x->x.getType()==Ipo.IpoType.SME).count());}}
